"""Pure ASGI tracing and failure handling, including responses generated by handlers."""

import logging
from time import perf_counter

from starlette.datastructures import Headers, MutableHeaders
from starlette.types import ASGIApp, Message, Receive, Scope, Send

from bidding_compliance.core.diagnostics import report_exception
from bidding_compliance.core.tracing import choose_request_id, request_id_context

from .errors import error_response

LOGGER = logging.getLogger("bidding_compliance.api")
METHODS = {"GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "TRACE", "CONNECT"}


class RequestContextMiddleware:
    def __init__(self, app: ASGIApp) -> None:
        self.app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return
        request_id = choose_request_id(Headers(scope=scope).get("x-request-id"))
        token = request_id_context.set(request_id)
        started_at = perf_counter()
        status_code = 500
        response_started = False

        async def traced_send(message: Message) -> None:
            nonlocal status_code, response_started
            if message["type"] == "http.response.start":
                response_started = True
                status_code = message["status"]
                MutableHeaders(scope=message)["X-Request-ID"] = request_id
            await send(message)

        try:
            try:
                await self.app(scope, receive, traced_send)
            except Exception as exception:
                report_exception(exception, request_id)
                LOGGER.error(
                    "request_failed",
                    extra={
                        "request_id": request_id,
                        "error_code": "INTERNAL_ERROR",
                    },
                )
                if response_started:
                    # Headers cannot be changed now; never expose the original exception.
                    raise RuntimeError("response interrupted") from exception
                await error_response(500)(scope, receive, traced_send)
        finally:
            route: object = getattr(scope.get("route"), "path", None)
            LOGGER.info(
                "request_completed",
                extra={
                    "request_id": request_id,
                    "method": scope["method"] if scope["method"] in METHODS else "OTHER",
                    "route": route if isinstance(route, str) else "unmatched",
                    "status_code": status_code,
                    "duration_ms": round((perf_counter() - started_at) * 1000, 3),
                },
            )
            request_id_context.reset(token)
